import {coreWorkQuestions} from './core-work.js';
// Versioned question IDs prevent new wording from reinterpreting old responses.
export function professionConfirmationState(state,record){const s=structuredClone(state);if(!record)return s;if(![1,2].includes(record.version)||!Array.isArray(record.professions))throw Error('Invalid defining-work replay.');const coreVersion=record.version===1?'0.42.0':'0.44.0';s._coreWorkVersion=coreVersion;s.profileJourney.coreWork??={};const seen=new Set();for(const p of record.professions){if(seen.has(p.id))throw Error('Duplicate core profession.');seen.add(p.id);const qs=coreWorkQuestions(p.id,{coreVersion});if(qs.length!==2||p.answers.length!==2)throw Error('Incomplete core work.');for(const q of qs){const a=p.answers.find(a=>a.questionId===q.id);if(!a||!['yes','no','unsure','unfamiliar'].includes(a.response)||!['high','medium','low'].includes(a.confidence)||!a.evidence?.trim())throw Error('Invalid core work answer.');s.profileJourney.coreWork[q.id]={response:a.response,confidence:a.confidence,evidence:a.evidence,source:'profile-inferred'};}}return s;}
